import sys
import xml.etree.ElementTree as ET
import json

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    settings = []
    for setting in root.findall('setting'):
        name = setting.get('name')
        value = setting.get('value')
        settings.append((name, value))
    return settings

def parse_json(json_path):
    with open(json_path, 'r') as f:
        return json.load(f)

def merge_settings(xml_settings, json_overrides):
    xml_names = {name for name, _ in xml_settings}
    merged = []
    json_names = json_overrides.keys()
    xml_index = 0

    for name in sorted(xml_names | json_names):
        if name in json_names:
            value = json_overrides[name]
            merged.append((name, value))
        else:
            if xml_index < len(xml_settings) and xml_settings[xml_index][0] == name:
                merged.append(xml_settings[xml_index])
                xml_index += 1
            else:
                raise ValueError(f"XML setting {name} not found in original XML")

    return merged

def generate_xml(root, settings):
    for name, value in settings:
        setting = ET.SubElement(root, 'setting', name=name, value=value)
    return ET.tostring(root, encoding='utf-8', method='xml')

def main():
    xml_path = sys.argv[1]
    json_path = sys.argv[2]

    xml_settings = parse_xml(xml_path)
    json_overrides = parse_json(json_path)
    merged_settings = merge_settings(xml_settings, json_overrides)

    root = ET.Element('config')
    for name, value in merged_settings:
        setting = ET.SubElement(root, 'setting', name=name, value=value)

    # Preserve original order of existing settings not in JSON
    for name, value in xml_settings:
        if name not in json_overrides:
            setting = ET.SubElement(root, 'setting', name=name, value=value)

    # Rebuild with merged settings in correct order
    root.clear()
    root = ET.Element('config')
    for name, value in merged_settings:
        setting = ET.SubElement(root, 'setting', name=name, value=value)

    # Add remaining original settings in order
    for name, value in xml_settings:
        if name not in json_overrides:
            setting = ET.SubElement(root, 'setting', name=name, value=value)

    print(generate_xml(root, merged_settings))

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import json

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    settings = []
    for setting in root.findall('setting'):
        name = setting.get('name')
        value = setting.get('value')
        settings.append((name, value))
    return root, settings

def parse_json(json_path):
    with open(json_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def merge_settings(xml_root, json_data):
    json_settings = json_data.items()
    existing_names = {name for name, _ in xml_root.findall('setting')}

    for name, value in json_settings:
        if name in existing_names:
            for setting in xml_root.findall('setting'):
                if setting.get('name') == name:
                    setting.set('value', value)
                    break
        else:
            new_setting = ET.SubElement(xml_root, 'setting')
            new_setting.set('name', name)
            new_setting.set('value', value)

def main():
    if len(sys.argv) != 3:
        print("Usage: python merge_config.py <xml_path> <json_path>")
        sys.exit(1)

    xml_path = sys.argv[1]
    json_path = sys.argv[2]

    xml_root, xml_settings = parse_xml(xml_path)
    json_data = parse_json(json_path)

    merge_settings(xml_root, json_data)

    tree = ET.ElementTree(xml_root)
    tree.write(sys.stdout, encoding='utf-8', xml_declaration=True)

if __name__ == "__main__":
    main()

import sys
import xml.etree.ElementTree as ET
import json

def parse_xml(xml_path):
    tree = ET.parse(xml_path)
    root = tree.getroot()
    return root

def parse_json(json_path):
    with open(json_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def merge_settings(xml_root, json_data):
    settings = list(xml_root)
    json_keys = set(json_data.keys())

    # Process existing settings first
    for setting in settings:
        if setting.attrib['name'] in json_keys:
            setting.attrib['value'] = json_data[setting.attrib['name']]

    # Collect remaining settings to add
    remaining_settings = json_keys - {s.attrib['name'] for s in settings}

    # Add new settings after existing ones
    for name in remaining_settings:
        value = json_data[name]
        new_setting = ET.Element('setting')
        new_setting.attrib['name'] = name
        new_setting.attrib['value'] = value
        xml_root.append(new_setting)

def serialize_xml(xml_root):
    ET.ElementTree(xml_root).write(sys.stdout, encoding='utf-8', xml_declaration=True)

def main():
    if len(sys.argv) != 3:
        print("Usage: python merge_config.py <xml_path> <json_path>", file=sys.stderr)
        sys.exit(1)

    xml_path = sys.argv[1]
    json_path = sys.argv[2]

    xml_root = parse_xml(xml_path)
    json_data = parse_json(json_path)

    merge_settings(xml_root, json_data)
    serialize_xml(xml_root)

if __name__ == "__main__":
    main()
